{
    param(
        [object]$TurnRequest,
        [object]$TurnNumber,
        [string]$RequestId,
        [string]$ExperiencePrompt,
        [string]$FirstMortalBootstrapPrompt
    )

    return "Process first Mortal bootstrap turn #$TurnNumber (requestId=$RequestId).$($script:GmContextPackDirective)$($script:GmDocPathDirective)$($script:GmSafeProbeDirective)$($script:GmSourceFallbackDirective)$($script:GmExperienceLessonsDirective)$($ExperiencePrompt)$($FirstMortalBootstrapPrompt)$($script:GmLiveTestRubricDirective)$($script:GmTurnHelperDirective) Read $GameSessionPath\input\turn_request.json, game_state/control/mortal_bootstrap_scaffold.json, '$($script:CompactTurnOutputTemplatePath)', '$($script:CompactActorReasoningTemplatePath)', and '$($script:CompactProgressionReportTemplatePath)' before writing output. This is a bounded bootstrap task packet: do not open broad examples, afterlife directives, weather guidance, combat guidance, faction/location/NPC/skill templates, or repository source. FIRST MORTAL BOOTSTRAP OUTPUT CHECKLIST: produce the minimum complete first mortal scene only: output/narrative_response.json, output/debug_logs.json with NPC Scope, output/interface_updates.json with clear choices, and game_state/control/progression_report.json only when progression counts are required. If the setting-neutral baseline files are already valid, preserve them and avoid rebuilding the world. playerAuthoredStart is narrative context only. The client creates no inferred skills, items, NPCs, capabilities, money, progression, carrying values, factions, quests, location type/traversal/difficulty, faction resources, influence/control, or universal powerProfile; experience.json starts as an empty structural object. Every structuredGmAuthority.playerProgression, carryingRules, or factionMechanics entry must name the exact canonicalPath and contain a non-empty values object that repeats every authorized canonical value; faction entries also identify factionId. Empty objects, reasons, unrelated paths, and prose do not grant authority. Record other setting-aware choices in playerSkills, inventoryItems, actorCapabilities, or resources and write matching complete canonical GM state; keep worldEventRequirements entries in world_events.json. Replace temporary scaffold labels only in identity/title fields: no accepted current location or exit/link may stay named 'Стартовая сцена', 'Путь из стартовой сцены', or 'Ближайший выход из стартовой сцены'; ordinary narrative prose may retain the same words. Every NPC first created on this turn requires the complete materialization envelope. A trader requires an explicit valid tradeState.merchantProfile; never infer it from role, occupation, class, name, description, genre, or keywords. If you must add or update a player-facing anchor from the scaffold, use the smallest matching compact Mortal template after the basic output files are ready. TERMINAL CHECKLIST: write EXACTLY ONE terminal signal for this request, copy exact sessionId/requestId/turnNumber from input/turn_request.json, never delete or rewrite input/turn_request.json or pending_turn_snapshot files, and finish with Complete-BoeTurn -FilesModified as the LAST action."
}

{
    param([string]$RequestPath)

    if ($script:IsProcessing) { return }
    $script:IsProcessing = $true

    try {
        Start-Sleep -Milliseconds 150
        $eligibility=Read-QteDaemonEligibility $RequestPath
        if($null -eq $eligibility){return}
        $pendingSnapshot = $eligibility.Pending
        $request = $pendingSnapshot.Request
        if (-not [string]::Equals(
                [string]$request.requestKind,
                "qte_deferred_effect_resolution",
                [System.StringComparison]::Ordinal) -or
            $null -eq $request.safePacket) {
            throw "Invalid dedicated QTE effect-resolution request."
        }

        $requestKey = Get-QteEffectResolutionRequestKey -Request $request
        if ([string]::IsNullOrWhiteSpace($requestKey.Replace("|", ""))) {
            throw "Dedicated QTE effect-resolution request has no correlation authority."
        }

        if ($eligibility.ReadyMatches) {
            Write-Log "  Found correlated QTE effect-resolution ready marker; waiting for client consumption." -Color DarkGray
            return
        }

        $startedAt = Get-Date
        $acceptedSourceTurn = if ($null -ne $request.acceptedSourceTurn) {
            [int]$request.acceptedSourceTurn
        } else {
            -1
        }
        Write-Host ""
        Write-Log "QTE effect receipt wave $($request.waveOrdinal) for source turn #$acceptedSourceTurn" -Level "QTE" -Color Cyan

        $message = Build-QteEffectResolutionDispatchMessage -Request $request
        $dispatchMaxWaitSeconds = if ($TurnTimeout -gt 0 -and $TurnTimeout -lt $script:BridgeDispatchMaxWaitSeconds) {
            $TurnTimeout
        } else {
            $script:BridgeDispatchMaxWaitSeconds
        }
        $dispatch = Dispatch-WithRetry `
            -Message $message `
            -PendingPath $RequestPath -ExpectedSourceHash $pendingSnapshot.Hash `
            -OperationKind qte-effect -OperationRevision $requestKey `
            -ReturnDetails `
            -MaxWaitSeconds $dispatchMaxWaitSeconds
        if (Test-GmPromptDispatchPaused $dispatch) {
            Write-Log "  QTE effect receipt request was cancelled before dispatch." -Level "WARN" -Color Yellow
            return
        }
        if ($dispatch.Status -eq "bridge-dispatch-timeout") {
            $script:ErrorCount++
            Write-Log "  GM bridge did not accept the QTE receipt packet; dedicated authority remains pending for retry." -Level "ERROR" -Color Red
            return
        }

        $elapsed = 0
        while ($TurnTimeout -le 0 -or $elapsed -lt $TurnTimeout) {
            if (Test-QteEffectResolutionReadyMatchesRequest `
                    -Request $request `
                    -ReadyPath $QteEffectResolutionReadyFile) {
                $duration = ((Get-Date) - $startedAt).TotalSeconds
                Write-Log "  QTE effect receipt wave ready ($([math]::Round($duration, 1))s)" -Level "QTE" -Color Green
                return
            }

            Start-Sleep -Seconds 1
            $elapsed++

            if (-not (Test-QteEffectResolutionRequestStillCurrent `
                    -RequestPath $RequestPath `
                    -ExpectedRequestKey $requestKey)) {
                Write-Log "  QTE effect receipt wait closed because client authority was removed or replaced." -Level "WARN" -Color Yellow
                return
            }

            if ($elapsed % 15 -eq 0 -and
                (Test-GmBridgeReturnedIdleWithoutTerminalSignal -ElapsedSeconds $elapsed)) {
                Write-Log "  GM bridge returned idle without the correlated QTE ready marker; preserving the original delivery without replay." -Level "WARN" -Color Yellow
                $operation = New-GmPromptOperation -Message $message -PendingPath $RequestPath -ExpectedSourceHash $pendingSnapshot.Hash -OperationKind qte-effect -OperationRevision $requestKey
                if ($operation) { $operation.LastDelivery = Invoke-GmPromptControl -Operation $operation -Command 'promptStatus' }
                $script:GmPromptInputPaused = $true
                return
            }

            if ($elapsed % 60 -eq 0) {
                Write-Log "  Waiting for QTE effect receipts... (${elapsed}s)" -Color DarkGray
                Update-DaemonProcessingHeartbeat `
                    -TurnNumber $acceptedSourceTurn `
                    -ElapsedSeconds $elapsed
            }
        }

        Write-Log "  QTE effect receipt wait reached the configured timeout; dedicated authority remains pending." -Level "WARN" -Color Yellow
    }
    catch {
        Assert-GmNotDaemonReadFailure $_
        $script:ErrorCount++
        Write-Log "  QTE effect receipt dispatch error: $_" -Level "ERROR" -Color Red
    }
    finally {
        Write-DaemonStatus -Status "running" -Reason "qte_effect_resolution_processing_finished"
        $script:IsProcessing = $false
    }
}

{
    param([string]$RequestPath)

    if ($script:IsProcessing) { return }
    $script:IsProcessing = $true

    try {
        Start-Sleep -Milliseconds 300
        if (!(Test-GmDaemonPath $RequestPath)) { return }
        $pendingSnapshot = Read-GmPromptPending -Path $RequestPath
        $turnRequest = $pendingSnapshot.Request
        $turnNumber = $turnRequest.turnNumber
        $turnRequestKey = Get-TurnRequestKey -TurnRequest $turnRequest
        if (Test-ObservedTerminalRequestKey -Key $turnRequestKey) {
            return
        }

        $samplingMismatch=$false
        if (-not (Test-TurnRequestHasPendingSnapshotContext -TurnRequest $turnRequest -RequestPath $RequestPath -ExpectedSourceHash $pendingSnapshot.Hash -SamplingMismatch ([ref]$samplingMismatch))) {
            if($samplingMismatch){return} # No coherent invalidity decision; do not suppress this request.
            Write-Log "  Skipping stale turn request without matching pending snapshot context (requestKey=$turnRequestKey)." -Level "WARN" -Color Yellow
            Add-ObservedTerminalRequestKey -Key $turnRequestKey
            return
        }

        $script:TurnCount++
        $turnStart = Get-Date

        $playerAction = if ($turnRequest.playerAction.Length -gt 80) {
            $turnRequest.playerAction.Substring(0, 77) + "..."
        } else { $turnRequest.playerAction }

        Write-Host ""
        Write-Log "Turn #${turnNumber}: $playerAction" -Level "TURN" -Color Green

        $null = Write-GmExperienceLessons
        $experiencePrompt = Get-GmExperiencePromptDigest
        $firstMortalBootstrapPrompt = Get-FirstMortalBootstrapPrompt -TurnRequest $turnRequest

        # Send processing command to CLI window
        $requestId = if ($turnRequest.requestId) { $turnRequest.requestId } else { "<missing-requestId>" }
        $message = $null
        if (-not [string]::IsNullOrWhiteSpace($firstMortalBootstrapPrompt)) {
            $message = Build-FirstMortalBootstrapDispatchMessage `
                -TurnRequest $turnRequest `
                -TurnNumber $turnNumber `
                -RequestId $requestId `
                -ExperiencePrompt $experiencePrompt `
                -FirstMortalBootstrapPrompt $firstMortalBootstrapPrompt
        }

        if ($null -eq $message) {
        $message = "Process turn #$turnNumber (requestId=$requestId).$($script:GmContextPackDirective)$($script:GmDocPathDirective)$($script:GmSafeProbeDirective)$($script:GmSourceFallbackDirective)$($script:GmCompactTemplateDirective)$($script:GmExperienceLessonsDirective)$($experiencePrompt)$($firstMortalBootstrapPrompt)$($script:GmLiveTestRubricDirective)$($script:GmTurnHelperDirective) Read $GameSessionPath\input\turn_request.json and follow CLI_Agent_Daemon_Specification.md phases 0-4. You MUST read '$($script:CompactTurnOutputTemplatePath)', '$($script:CompactProgressionReportTemplatePath)', '$($script:CompactActorReasoningTemplatePath)', '$($script:CompactMortalNpcTemplatePath)', '$($script:CompactMortalFactionTemplatePath)', '$($script:CompactMortalLocationTemplatePath)', '$($script:CompactMortalSkillTemplatePath)', '$($script:CompactMortalExperienceTemplatePath)', '$($script:CompactAfterlifeChronicleTemplatePath)', and '$($script:CompactTempoAdvantageTemplatePath)' before opening large copied examples. Read '$($script:TaskGuideMainPath)' for phase rules; use '$($script:ExampleMainPath)' only when compact templates do not cover a route-specific shape.$($script:AfterlifeRealmGateDirective)$($script:AfterlifeExamplesDirective)$($script:AfterlifeCombatConditionsDirective)$($script:AfterlifeSpecialArtCombatEffectDirective) $($script:WeatherContractDirective) If this turn uses any GM-side [INK_FEATHER_ACTION: TAG], you MUST also read '$($script:InkFeatherExamplePath)' and write output/ink_feather_action_result.json with exact metadata, actionTag, resolved=true, costInFeathers, resolutionType, summary, and stateEvidence. The client validates correlated metadata, valid JSON, realm restrictions, progressionControl/progression report, gm_thoughts_markdown scope/reasoning, and structured actor coverage. Relevant actors in NPC scope MUST cover any structured actor updates such as NPCCoreChanges, UpdateNPCs, NPCGoalUpdates, or UpdateGuardians. If a Mortal World turn creates or updates NPCs, use '$($script:CompactMortalNpcTemplatePath)' before editing game_state/npcs/npc_core.json. If a Mortal World turn creates or updates factions, ranks, branches, chronicles, projects, faction relations, or faction sidecars, use '$($script:CompactMortalFactionTemplatePath)' before editing game_state/factions/*. If a Mortal World turn creates a durable location, changes current_location, edits world_map, or moves NPCs between map locations, use '$($script:CompactMortalLocationTemplatePath)' before editing game_state/world/* or NPC location ids. If a Mortal World turn teaches, practices, unlocks, or uses a concrete player skill, use '$($script:CompactMortalSkillTemplatePath)' before writing output/state; do not leave learned skills or active-skill mastery as prose-only text. If a Mortal World turn grants XP, resolves combat rewards, or crosses a level-up threshold, use '$($script:CompactMortalExperienceTemplatePath)' before editing game_state/player/experience.json; do not leave level progress prose-only. Use preGeneratedDices1d20 from the FIRST die for normal checks; afterlife spiritual conflicts use visible d20 values through diceAudit on contested exchange/resolve; gachaBaseResult is separate and does not consume visible dice. If playerAction contains [CHAOS_SEA_DIRECT_GACHA], treat it as a neutral direct pull from the Chaos Sea, not a Guardian-mediated pull, and preserve the exact cost phrase '<N> Чернильных Перьев' or '<N> Ink Feathers' because validation extracts prepaid cost from it. Guardian-mediated gacha is limited per Guardian per return from mortal life: Hostile=0, Wary/Neutral=1, Friendly=2, Devoted/Legendary=3. Guardian-mediated rarity upgrades are limited to Abode Power rarity ceiling bonus and completed relic_forging project bonus; Guardian reputation does not improve rarity odds. Charges reset only when the Soul returns to the Chaos Sea after a new mortal life. If a Guardian has no remaining charges this return, do NOT emit UpdateGuardians.processGacha for that Guardian. Direct /gacha remains neutral and does NOT consume Guardian charges. progressionControl in the request is authoritative. If progression is processed, write game_state/control/progression_report.json with exact sessionId/requestId/turnNumber copied from the CURRENT turn_request.json plus exact bounded processed cycle counts and new last-* markers. If progressionControl.afterlifeCatchupRequired=true, process only afterlifeCatchupSummaryEventsRequired summary outcomes and do NOT simulate raw elapsed cycles one by one. TERMINAL CHECKLIST: write EXACTLY ONE terminal signal for this request; use either ready/turn_complete.json OR ready/turn_error.json, never both; copy exact sessionId/requestId/turnNumber from the CURRENT turn_request.json; never delete or rewrite input/turn_request.json; write the terminal signal as the LAST step. If you write both terminal files or wrong metadata, the client will reject the terminal phase as protocol failure and write game_state/control/terminal_protocol_failure_request.json. validation_repair_request.json is only for accepted terminal completion with invalid resulting state."

        $message += " If a Mortal World turn resolves open combat, enemy exchange, combat XP, active-skill combat mastery, or combat resource changes, you MUST read '$($script:CompactMortalCombatTemplatePath)' before writing output/state and leave /бой useful through game_state/combat/combat_log.json plus enemies/allies when relevant."
        }
        $completionPath = Join-Path $ReadyDir "turn_complete.json"
        $errorPath = Join-Path $ReadyDir "turn_error.json"
        $terminalSignal = Get-CorrelatedTerminalSignal -TurnRequest $turnRequest -CompletionPath $completionPath -ErrorPath $errorPath
        $dispatchDiagnostics = New-GmDispatchDiagnostics -Status "preexisting-terminal"
        $missingHarnessTool = $null

        if ($null -eq $terminalSignal) {
            $dispatchMaxWaitSeconds = if ($TurnTimeout -gt 0 -and $TurnTimeout -lt $script:BridgeDispatchMaxWaitSeconds) { $TurnTimeout } else { $script:BridgeDispatchMaxWaitSeconds }
            $dispatchDiagnostics = Dispatch-WithRetry -Message $message -PendingPath $RequestPath -ExpectedSourceHash $pendingSnapshot.Hash -OperationKind turn -ReturnDetails -MaxWaitSeconds $dispatchMaxWaitSeconds
            if (Test-GmPromptDispatchPaused $dispatchDiagnostics) {
                Write-Log "  Turn cancelled while waiting for bridge turn dispatch" -Level "WARN" -Color Yellow
                Write-GmTrajectoryRecord `
                    -Kind "turn" `
                    -Mode "ordinary" `
                    -RequestObject $turnRequest `
                    -Dispatch $dispatchDiagnostics `
                    -ValidationStatus "not_run" `
                    -RepairStatus "interrupted" `
                    -StartedAtUtc $turnStart.ToUniversalTime() `
                    -DurationSeconds ((Get-Date) - $turnStart).TotalSeconds `
                    -MissingHarnessTool "turn_cancelled_before_dispatch"
                return
            }

            if ($dispatchDiagnostics.Status -eq "bridge-dispatch-timeout") {
                if (-not (Test-GmPromptSourceCurrent -Path $RequestPath -Hash $pendingSnapshot.Hash)) { return }
                $script:ErrorCount++
                Write-Log "  GM bridge did not accept dispatch before the dispatch timeout; emitting daemon terminal error." -Level "ERROR" -Color Red
                $missingHarnessTool = "gm_bridge_dispatch_unavailable"
                $dispatchTerminalSignal = @{
                    sessionId = $turnRequest.sessionId
                    requestId = $turnRequest.requestId
                    turnNumber = $turnNumber
                    status = "error"
                    harnessSource = "gm_bridge_dispatch_unavailable"
                    timestamp = (Get-Date).ToUniversalTime().ToString("o")
                    error = "GM bridge did not accept dispatch before the dispatch timeout."
                }
                Write-GmCanonicalText -SessionPath $GameSessionPath -Path $errorPath -Value ($dispatchTerminalSignal | ConvertTo-Json -Depth 4)
                Write-GmTrajectoryRecord `
                    -Kind "turn" `
                    -Mode "ordinary" `
                    -RequestObject $turnRequest `
                    -Dispatch $dispatchDiagnostics `
                    -ValidationStatus "rejected" `
                    -TerminalSignal ([pscustomobject]@{
                        Path = $errorPath
                        Kind = "error"
                        Signal = [pscustomobject]$dispatchTerminalSignal
                    }) `
                    -StartedAtUtc $turnStart.ToUniversalTime() `
                    -DurationSeconds ((Get-Date) - $turnStart).TotalSeconds `
                    -MissingHarnessTool $missingHarnessTool
                Add-ObservedTerminalRequestKey -Key $turnRequestKey
                return
            }
        }
        elseif ($terminalSignal.Kind -eq "conflict") {
            Write-Log "  Detected conflicting correlated terminal signals for the same turn. Waiting stops as protocol failure; client should emit terminal_protocol_failure_request.json." -Level "ERROR" -Color Red
        }
        else {
            Write-Log "  Found correlated terminal signal already present; completing without re-dispatch" -Level "WARN" -Color Yellow
        }

        # Wait for terminal signal
        # A captured correlated terminal may still be logged after client consumption.
        # Replacement bytes never inherit that observation; no new terminal writes use this exception.
        if (-not (Test-GmPromptSourceCurrent -Path $RequestPath -Hash $pendingSnapshot.Hash) -and
            ($null -eq $terminalSignal -or (Test-GmDaemonPath $RequestPath))) { return }
        $elapsed = 0
        $artifactWriteStallWatchState = @{}
        $outputWithoutTerminalWatchState = New-GmOutputWithoutTerminalWatchState

        while ($null -eq $terminalSignal -and ($TurnTimeout -le 0 -or $elapsed -lt $TurnTimeout)) {
            Start-Sleep -Seconds 1
            $elapsed++

            # The old invocation cannot act on replacement bytes, even if snapshot context still matches.
            if (-not (Test-GmPromptSourceCurrent -Path $RequestPath -Hash $pendingSnapshot.Hash)) { return }
            if (!(Test-GmDaemonPath $RequestPath)) {
                Write-Log "  Turn cancelled by client" -Level "WARN" -Color Yellow
                break
            }

            $samplingMismatch=$false
            if (-not (Test-TurnRequestHasPendingSnapshotContext -TurnRequest $turnRequest -RequestPath $RequestPath -ExpectedSourceHash $pendingSnapshot.Hash -SamplingMismatch ([ref]$samplingMismatch))) {
                if($samplingMismatch){return}
                Write-Log "  Turn wait closed because the client no longer has matching pending snapshot context. The client likely consumed the terminal signal first." -Level "WARN" -Color Yellow
                Add-ObservedTerminalRequestKey -Key $turnRequestKey
                break
            }

            $terminalSignal = Get-CorrelatedTerminalSignal -TurnRequest $turnRequest -CompletionPath $completionPath -ErrorPath $errorPath
            if (-not (Test-GmPromptSourceCurrent -Path $RequestPath -Hash $pendingSnapshot.Hash) -and
                ($null -eq $terminalSignal -or (Test-GmDaemonPath $RequestPath))) { return }

            if ($null -eq $terminalSignal -and $elapsed % 15 -eq 0 -and (Test-GmBridgeReturnedIdleWithoutTerminalSignal -ElapsedSeconds $elapsed)) {
                if (-not (Test-GmPromptSourceCurrent -Path $RequestPath -Hash $pendingSnapshot.Hash)) { return }
                $script:ErrorCount++
                Write-Log "  GM bridge returned to idle without a correlated terminal signal; emitting daemon terminal error instead of waiting for full timeout." -Level "ERROR" -Color Red
                $missingHarnessTool = "gm_bridge_idle_without_terminal_signal"
                $idleTerminalSignal = @{
                    sessionId = $turnRequest.sessionId
                    requestId = $turnRequest.requestId
                    turnNumber = $turnNumber
                    status = "error"
                    harnessSource = "gm_bridge_idle_without_terminal_signal"
                    timestamp = (Get-Date).ToUniversalTime().ToString("o")
                    error = "GM bridge returned to idle without a correlated terminal signal."
                }
                Write-GmCanonicalText -SessionPath $GameSessionPath -Path $errorPath -Value ($idleTerminalSignal | ConvertTo-Json -Depth 4)
                $terminalSignal = [pscustomobject]@{
                    Path = $errorPath
                    Kind = "error"
                    Signal = [pscustomobject]$idleTerminalSignal
                }
                break
            }

            if ($null -eq $terminalSignal -and $elapsed % 15 -eq 0) {
                $payloadStall = Test-GmOutputWithoutTerminalSignal -ElapsedSeconds $elapsed -WatchState $outputWithoutTerminalWatchState
                if (-not (Test-GmPromptSourceCurrent -Path $RequestPath -Hash $pendingSnapshot.Hash)) { return }
                if ($null -ne $payloadStall -and $payloadStall.isStalled) {
                    $script:ErrorCount++
                    Write-Log "  GM wrote turn payload files without a correlated terminal signal; emitting daemon terminal error before indefinite wait." -Level "ERROR" -Color Red
                    $missingHarnessTool = "gm_output_without_terminal_signal"
                    $payloadCleanup = Stop-GmBridgeAfterTurnTimeout -TurnRequest $turnRequest -ElapsedSeconds $elapsed -Reason "gm_output_without_terminal_signal"
                    if (-not (Test-GmPromptSourceCurrent -Path $RequestPath -Hash $pendingSnapshot.Hash)) { return }
                    $payloadStall | Add-Member -NotePropertyName timeoutBridgeCleanup -NotePropertyValue $payloadCleanup -Force
                    [void](Write-DaemonJsonFileBestEffort -Path $OutputWithoutTerminalReportFile -Payload $payloadStall -Depth 10)
                    $payloadTerminalSignal = @{
                        sessionId = $turnRequest.sessionId
                        requestId = $turnRequest.requestId
                        turnNumber = $turnNumber
                        status = "error"
                        harnessSource = "gm_output_without_terminal_signal"
                        timestamp = (Get-Date).ToUniversalTime().ToString("o")
                        error = "GM wrote turn payload files without a correlated terminal signal."
                        changedFiles = $payloadStall.changedFiles
                        outputWithoutTerminal = $payloadStall
                    }
                    Write-GmCanonicalText -SessionPath $GameSessionPath -Path $errorPath -Value ($payloadTerminalSignal | ConvertTo-Json -Depth 12)
                    $terminalSignal = [pscustomobject]@{
                        Path = $errorPath
                        Kind = "error"
                        Signal = [pscustomobject]$payloadTerminalSignal
                    }
                    break
                }

                $artifactStall = Test-GmBridgeArtifactWritingStall -ElapsedSeconds $elapsed -WatchState $artifactWriteStallWatchState
                if (-not (Test-GmPromptSourceCurrent -Path $RequestPath -Hash $pendingSnapshot.Hash)) { return }
                if ($null -ne $artifactStall -and $artifactStall.isStalled) {
                    $script:ErrorCount++
                    Write-Log "  GM bridge appears stalled while preparing turn artifacts; emitting daemon terminal error before full timeout." -Level "ERROR" -Color Red
                    $missingHarnessTool = "gm_bridge_artifact_write_stall"
                    $artifactCleanup = Stop-GmBridgeAfterTurnTimeout -TurnRequest $turnRequest -ElapsedSeconds $elapsed -Reason "gm_bridge_artifact_write_stall"
                    if (-not (Test-GmPromptSourceCurrent -Path $RequestPath -Hash $pendingSnapshot.Hash)) { return }
                    $artifactStall | Add-Member -NotePropertyName timeoutBridgeCleanup -NotePropertyValue $artifactCleanup -Force
                    [void](Write-DaemonJsonFileBestEffort -Path $ArtifactWriteStallReportFile -Payload $artifactStall -Depth 10)
                    $artifactTerminalSignal = @{
                        sessionId = $turnRequest.sessionId
                        requestId = $turnRequest.requestId
                        turnNumber = $turnNumber
                        status = "error"
                        harnessSource = "gm_bridge_artifact_write_stall"
                        timestamp = (Get-Date).ToUniversalTime().ToString("o")
                        error = "GM bridge appears stalled while preparing turn artifacts."
                        artifactWriteStall = $artifactStall
                    }
                    Write-GmCanonicalText -SessionPath $GameSessionPath -Path $errorPath -Value ($artifactTerminalSignal | ConvertTo-Json -Depth 12)
                    $terminalSignal = [pscustomobject]@{
                        Path = $errorPath
                        Kind = "error"
                        Signal = [pscustomobject]$artifactTerminalSignal
                    }
                    break
                }
            }

            if ($elapsed % 60 -eq 0) {
                Write-Log "  Waiting... (${elapsed}s)" -Color DarkGray
                Update-DaemonProcessingHeartbeat -TurnNumber $turnNumber -ElapsedSeconds $elapsed
            }
        }

        if ($TurnTimeout -gt 0 -and $elapsed -ge $TurnTimeout -and $null -eq $terminalSignal) {
            if (-not (Test-GmPromptSourceCurrent -Path $RequestPath -Hash $pendingSnapshot.Hash)) { return }
            $script:ErrorCount++
            Write-Log "  Timeout after ${elapsed}s" -Level "ERROR" -Color Red
            $dispatchDiagnostics.Timeout = $true
            $missingHarnessTool = "gm_turn_timeout"
            $timeoutBridgeCleanup = Stop-GmBridgeAfterTurnTimeout -TurnRequest $turnRequest -ElapsedSeconds $elapsed
            if (-not (Test-GmPromptSourceCurrent -Path $RequestPath -Hash $pendingSnapshot.Hash)) { return }
            $timeoutSignal = @{
                sessionId = $turnRequest.sessionId
                requestId = $turnRequest.requestId
                turnNumber = $turnNumber
                status = "error"
                harnessSource = "gm_daemon_timeout"
                timestamp = (Get-Date).ToUniversalTime().ToString("o")
                error = "Timeout after ${elapsed}s"
                timeoutBridgeCleanup = $timeoutBridgeCleanup
            }
            Write-GmCanonicalText -SessionPath $GameSessionPath -Path $errorPath -Value ($timeoutSignal | ConvertTo-Json -Depth 8)
            $terminalSignal = [pscustomobject]@{
                Path = $errorPath
                Kind = "error"
                Signal = [pscustomobject]$timeoutSignal
            }
        }

        # Check terminal outcome
        if ($null -ne $terminalSignal -and $terminalSignal.Kind -eq "conflict") {
            $duration = ((Get-Date) - $turnStart).TotalSeconds
            Write-Log "  Terminal protocol conflict ($([math]::Round($duration, 1))s): both turn_complete.json and turn_error.json match the same request" -Level "TURN" -Color Red
            Write-GmTrajectoryRecord `
                -Kind "turn" `
                -Mode "ordinary" `
                -RequestObject $turnRequest `
                -Dispatch $dispatchDiagnostics `
                -ValidationStatus "rejected" `
                -TerminalSignal $terminalSignal `
                -StartedAtUtc $turnStart.ToUniversalTime() `
                -DurationSeconds $duration `
                -MissingHarnessTool "terminal_signal_conflict"
        }
        elseif ($null -ne $terminalSignal -and $terminalSignal.Kind -eq "success") {
            $duration = ((Get-Date) - $turnStart).TotalSeconds
            $repairGraceMs = if ($dispatchDiagnostics.Status -eq "preexisting-terminal") { 0 } else { $script:CorrelatedRepairGraceMilliseconds }
            $correlatedRepair = Wait-CorrelatedValidationRepairRequest -TurnRequest $turnRequest -GraceMilliseconds $repairGraceMs
            if ($null -ne $correlatedRepair) {
                Write-Log "  Done, but correlated validation repair is pending ($([math]::Round($duration, 1))s)" -Level "TURN" -Color Yellow
                Write-GmTrajectoryRecord `
                    -Kind "turn" `
                    -Mode "ordinary" `
                    -RequestObject $turnRequest `
                    -Dispatch $dispatchDiagnostics `
                    -ValidationStatus "rejected" `
                    -IssueKinds (Get-GmTrajectoryIssueKinds -RequestObject $correlatedRepair) `
                    -RepairPacketRefs (Get-GmTrajectoryRepairPacketRefs -RequestObject $correlatedRepair) `
                    -ValidationDiagnostics (Get-GmTrajectoryValidationDiagnostics -RequestObject $correlatedRepair) `
                    -RepairPacketDiagnostics (Get-GmTrajectoryRepairPacketDiagnostics -RequestObject $correlatedRepair) `
                    -RepairAttempts (Get-GmValidationRepairAttempt -RepairRequest $correlatedRepair) `
                    -RepairStatus "requested" `
                    -TerminalSignal $terminalSignal `
                    -StartedAtUtc $turnStart.ToUniversalTime() `
                    -DurationSeconds $duration
            }
            else {
                Write-Log "  Done ($([math]::Round($duration, 1))s)" -Level "TURN" -Color Green
                Write-GmTrajectoryRecord `
                    -Kind "turn" `
                    -Mode "ordinary" `
                    -RequestObject $turnRequest `
                    -Dispatch $dispatchDiagnostics `
                    -ValidationStatus "accepted" `
                    -TerminalSignal $terminalSignal `
                    -StartedAtUtc $turnStart.ToUniversalTime() `
                    -DurationSeconds $duration
            }
        }
        elseif ($null -ne $terminalSignal -and $terminalSignal.Kind -eq "error") {
            $duration = ((Get-Date) - $turnStart).TotalSeconds
            try {
                $errorSignal = $terminalSignal.Signal
                $errorMessage = if ($errorSignal.error) { $errorSignal.error } else { "Unknown GM error" }
                Write-Log "  Terminal error ($([math]::Round($duration, 1))s): $errorMessage" -Level "TURN" -Color Yellow
            }
            catch {
        Assert-GmNotDaemonReadFailure $_
                Write-Log "  Terminal error ($([math]::Round($duration, 1))s): unreadable turn_error.json" -Level "TURN" -Color Yellow
            }
            if ([string]::IsNullOrWhiteSpace($missingHarnessTool)) {
                $missingHarnessTool = Get-MissingHarnessToolFromTerminalError -TerminalSignal $terminalSignal
            }
            Write-GmTrajectoryRecord `
                -Kind "turn" `
                -Mode "ordinary" `
                -RequestObject $turnRequest `
                -Dispatch $dispatchDiagnostics `
                -ValidationStatus "rejected" `
                -TerminalSignal $terminalSignal `
                -StartedAtUtc $turnStart.ToUniversalTime() `
                -DurationSeconds $duration `
                -MissingHarnessTool $missingHarnessTool
        }

        if ($null -ne $terminalSignal) {
            Add-ObservedTerminalRequestKey -Key $turnRequestKey
        }
    }
    catch {
        Assert-GmNotDaemonReadFailure $_
        $script:ErrorCount++
        Write-Log "  Error: $_" -Level "ERROR" -Color Red
    }
    finally {
        Write-DaemonStatus -Status "running" -Reason "turn_processing_finished"
        $script:IsProcessing = $false
    }
}

{
    param([string]$RepairPath)

    if (!(Test-GmDaemonPath $RepairPath)) { return }

    try {
        $pendingSnapshot = Read-GmPromptPending -Path $RepairPath
        $fileInfo = [pscustomobject]@{LastWriteTimeUtc=$pendingSnapshot.LastWriteTimeUtc}
        if ($fileInfo.LastWriteTimeUtc -le $script:LastRepairRequestWrite) { return }
        $script:LastRepairRequestWrite = $fileInfo.LastWriteTimeUtc
        $repair = $pendingSnapshot.Request
        $turnNumber = if ($repair.turnNumber) { [int]$repair.turnNumber } else { -1 }
        $requestId = if ($repair.requestId) { $repair.requestId } else { "<missing-requestId>" }
        $attempt = if ($repair.revalidationAttempt) { [int]$repair.revalidationAttempt } else { 1 }
        $hasDiagnosticOnlyMetadata = Test-ProtocolRequestUsesDiagnosticOnlyMetadata -RequestObject $repair

        $summary = @()
        if ($repair.summaryGroups) {
            foreach ($group in @($repair.summaryGroups | Select-Object -First 6)) {
                if ($group) { $summary += "- $group" }
            }
        }

        $topErrors = @()
        if ($repair.errors) {
            foreach ($err in @($repair.errors | Select-Object -First 5)) {
                $code = if ($err.code) { $err.code } else { "validation_error" }
                $category = if ($err.category) { $err.category } else { "StateConsistency" }
                $section = if ($err.section) { $err.section } else { "General" }
                $msg = if ($err.message) { $err.message } else { "Unknown validation error" }
                $expected = if ($err.expected) { " Expected: $($err.expected)" } else { "" }
                $actual = if ($err.actual) { " Actual: $($err.actual)" } else { "" }
                $hint = if ($err.repairHint) { " Hint: $($err.repairHint)" } else { "" }
                $topErrors += "- [$category/$section/$code] $msg$expected$actual$hint"
            }
        }

        $repairPacketKinds = @()
        foreach ($packetCollectionName in @("harnessRepairPackets", "repairPackets")) {
            $packetCollection = $repair.PSObject.Properties[$packetCollectionName]
            if ($null -ne $packetCollection -and $null -ne $packetCollection.Value) {
                foreach ($packet in @($packetCollection.Value)) {
                    if ($null -ne $packet.kind -and -not [string]::IsNullOrWhiteSpace([string]$packet.kind)) {
                        $repairPacketKinds += [string]$packet.kind
                    }
                }
            }
        }

        $issueCodes = @()
        if ($repair.errors) {
            foreach ($err in @($repair.errors)) {
                if ($err.code) { $issueCodes += [string]$err.code }
            }
        }

        $hasAcceptedTurnOutputArtifactRepair = @($repairPacketKinds | Where-Object { [string]::Equals($_, "accepted_turn_output_artifact_repair", [System.StringComparison]::OrdinalIgnoreCase) }).Count -gt 0
        $hasMortalLocationMaterializationRepair = @($repairPacketKinds | Where-Object { [string]::Equals($_, "mortal_location_materialization_repair", [System.StringComparison]::OrdinalIgnoreCase) }).Count -gt 0
        $hasEffectMaterializationRepair = @($repairPacketKinds | Where-Object { [string]::Equals($_, "effect_materialization_repair", [System.StringComparison]::OrdinalIgnoreCase) }).Count -gt 0
        $hasResourceSemanticOmissionRepair = @($repairPacketKinds | Where-Object { [string]::Equals($_, "resource_semantic_omission_repair", [System.StringComparison]::OrdinalIgnoreCase) }).Count -gt 0
        $requiresFullTurnResubmission = ($repair.fullTurnResubmissionRequired -eq $true) -or
            $hasMortalLocationMaterializationRepair -or
            $hasEffectMaterializationRepair -or
            $hasResourceSemanticOmissionRepair
        $hasGuardianPendingCreationRepair = @($repairPacketKinds | Where-Object { [string]::Equals($_, "guardian_pending_creation_materialization_repair", [System.StringComparison]::OrdinalIgnoreCase) }).Count -gt 0
        $hasGuardianTradeInventoryRepair = @($repairPacketKinds | Where-Object { [string]::Equals($_, "guardian_trade_inventory_resolution_repair", [System.StringComparison]::OrdinalIgnoreCase) }).Count -gt 0
        $hasStalePlayerFacingOutputRepair = @($issueCodes | Where-Object { [string]::Equals($_, "accepted_turn_stale_player_facing_output_after_canonical_repair", [System.StringComparison]::OrdinalIgnoreCase) }).Count -gt 0
        $hasGuardianPendingCreationIssue = @($issueCodes | Where-Object {
            [string]::Equals($_, "guardian_materialized_without_create_surface", [System.StringComparison]::OrdinalIgnoreCase) -or
            [string]::Equals($_, "stale_pending_guardian_creation_after_materialization", [System.StringComparison]::OrdinalIgnoreCase) -or
            [string]::Equals($_, "pending_guardian_creation_missing_materialized_guardian", [System.StringComparison]::OrdinalIgnoreCase) -or
            [string]::Equals($_, "pending_guardian_creation_unresolved_after_startup_turn", [System.StringComparison]::OrdinalIgnoreCase)
        }).Count -gt 0
        $hasGuardianTradeInventoryIssue = @($issueCodes | Where-Object {
            [string]::Equals($_, "guardian_trade_request_missing_guardian_resolution", [System.StringComparison]::OrdinalIgnoreCase) -or
            [string]::Equals($_, "guardian_trade_request_missing_inventory_resolution", [System.StringComparison]::OrdinalIgnoreCase) -or
            [string]::Equals($_, "guardian_trade_request_missing_receipt_resolution", [System.StringComparison]::OrdinalIgnoreCase)
        }).Count -gt 0
        $outputArtifactRepairDirective = if ($hasAcceptedTurnOutputArtifactRepair -or $hasStalePlayerFacingOutputRepair) {
            " You MUST read '$($script:CompactOutputArtifactRepairTemplatePath)' before any broad repair examples. For accepted_turn_output_artifact_repair, harnessRepairPackets[].targetFiles is the exact allowlist. Rewrite only listed artifacts; if output/debug_logs.json is absent, preserve it unchanged, and if listed, preserve its full Actor Brain blocks and exact journal/ledger surfaces. Do not mention JSON, validation, repair, canonical state, arrays, file paths, field names, or storage mechanics inside narrative_response.response. Do not touch canonical game_state files unless the current request still lists canonical errors; if it does, finish every canonical write before dependent output because freshness follows the latest actual canonical-target write, not repair start."
        } else {
            ""
        }
        $mortalLocationRepairDirective = if ($hasMortalLocationMaterializationRepair) {
            " For mortal_location_materialization_repair, you MUST read '$($script:CompactMortalLocationTemplatePath)' and the current packet before editing anything. The client restored the validated pre-turn baseline before dispatch. Perform full-turn resubmission for this same request: regenerate one complete coherent raw response containing every intended location, actor, faction, item, narrative, interface, and other changed output named by requiredResubmissionPaths/resubmissionObligations. Do not patch canonical world_map/current_location/location_identity_index files in place, submit only the named leaf, reuse stale output, make a formatting-only rewrite, or send only validation_repair_ready.json."
        } else {
            ""
        }
        $acceptedMechanicsFullTurnRepairDirective = if ($hasEffectMaterializationRepair -or $hasResourceSemanticOmissionRepair) {
            " For effect_materialization_repair or resource_semantic_omission_repair, fullTurnResubmissionRequired=true means the validated baseline was restored. Regenerate the same complete semantic turn. requiredResubmissionPaths is the exact list of changed GM-authored command/output surfaces and every listed path must be freshly rewritten. Client-owned system_mods, progression_schedule, resource definitions/state/history/owner authority, pending_effect_resolutions, and effect_identity_index are restored or published by the client and must never be written or added to that list."
        } else {
            ""
        }
        $guardianPendingCreationRepairDirective = if ($hasGuardianPendingCreationRepair -or $hasGuardianPendingCreationIssue) {
            " For startup Guardian creation repairs, use validation_repair_request.json.harnessRepairPackets[] kind guardian_pending_creation_materialization_repair before broad Guardian examples. Read game_state/meta/guardians.json.pendingGuardianCreation as startup authority; for a New Game freeform startup request, write UpdateGuardians.create as the UpdateGuardians[] JSON array with command=create and data=<full canonical Guardian> as the authority. Start from harnessRepairPackets[].canonicalCreateSkeleton and allowedEnums, then mirror that result into guardians[] + activeGuardian + chaosSeaNavigation and remove pendingGuardianCreation. Do not repair only materialized mirrors, keep pendingGuardianCreation as a pending-only fallback, delete it alone, or leave the Guardian only in prose."
        } else {
            ""
        }
        $guardianTradeInventoryRepairDirective = if ($hasGuardianTradeInventoryRepair -or $hasGuardianTradeInventoryIssue) {
            " For Guardian trade inventory repairs, use validation_repair_request.json.harnessRepairPackets[] kind guardian_trade_inventory_resolution_repair before broad examples. Read game_state/control/pending_guardian_trade_request.json as read-only authority, keep it unchanged, patch only the matching guardian.tradeInventory and tradeInventoryReceipts/UpdateGuardianTradeInventoryReceipts in game_state/meta/guardians.json, and finish the repair; do not create a new turn or leave the vitrine in prose."
        } else {
            ""
        }

        $repairExecutionDirective = if ($requiresFullTurnResubmission) {
            " Regenerate the complete required response package from the restored baseline; this is not an in-place patch. When requiredResubmissionPaths is non-empty, it is the exact GM-authored replay obligation."
        } else {
            " Fix only the listed validation errors in the already written files IN PLACE."
        }
        $readyPath = "$GameSessionPath\game_state\control\validation_repair_ready.json"
        $message = "REPAIR MODE for rejected turn #$turnNumber (requestId=$requestId, attempt=$attempt).$($script:GmContextPackDirective)$($script:GmDocPathDirective)$($script:GmSafeProbeDirective)$($script:GmSourceFallbackDirective)$($script:GmCompactTemplateDirective)$($script:GmExperienceLessonsDirective)$($script:GmLiveTestRubricDirective)$($script:GmTurnHelperDirective) You MUST reread $GameSessionPath\game_state\control\validation_repair_request.json and '$($script:CompactValidationRepairTemplatePath)' before opening large copied examples.$outputArtifactRepairDirective$mortalLocationRepairDirective$acceptedMechanicsFullTurnRepairDirective$guardianPendingCreationRepairDirective$guardianTradeInventoryRepairDirective Also use '$($script:CompactActorReasoningTemplatePath)' for actor coverage repairs; use '$($script:CompactMortalNpcTemplatePath)' for any repair touching game_state/npcs/npc_core.json or NPC validation errors; use '$($script:CompactMortalFactionTemplatePath)' for any repair touching game_state/factions/* or faction validation errors; use '$($script:CompactMortalLocationTemplatePath)' for any repair touching game_state/world/current_location.json, game_state/world/world_map.json, or unknown location ids; use '$($script:CompactMortalSkillTemplatePath)' for any repair touching activeSkillChanges, passiveSkillChanges, skillMasteryChanges, or player skill files; use '$($script:CompactMortalExperienceTemplatePath)' for any repair touching game_state/player/experience.json, experienceGained, level-up, or stat-point level progression; and prefer validation_repair_request.json.harnessRepairPackets over source-code archaeology. Read '$($script:TaskGuideMainPath)' for repair phase rules; use '$($script:ExampleMainPath)' only when compact templates do not cover a route-specific shape.$($script:AfterlifeRealmGateDirective)$($script:AfterlifeExamplesDirective)$($script:AfterlifeCombatConditionsDirective)$($script:AfterlifeSpecialArtCombatEffectDirective)$repairExecutionDirective Do NOT create a new turn. Do NOT run unrelated git or repository tasks. Do NOT wait for another prompt after files are fixed; finish the repair protocol immediately. never write ready/turn_complete.json for repair."
        if ($hasDiagnosticOnlyMetadata) {
            $message += " The current repair request marks sessionId/requestId/turnNumber as diagnostic-only sentinel values because validated pending snapshot context is unavailable or invalid. Do NOT copy those sentinel metadata into $readyPath. First restore pending snapshot context/authority and then use the freshest client-authored repair request with valid metadata before writing validation_repair_ready.json."
        }
        else {
            $message += " Terminal marker: after the files are fixed, create $readyPath with matching sessionId/requestId/turnNumber copied from the CURRENT repair request as the LAST action. If the files already satisfy the listed errors, create $readyPath immediately as the LAST action."
        }
        $message += " If your ready file is malformed or mismatched, the client will reject it and rewrite the repair request again. $($script:WeatherContractDirective)"
        if ($summary.Count -gt 0) {
            $message += "`nMain groups:`n" + ($summary -join "`n")
        }
        if ($topErrors.Count -gt 0) {
            $message += "`nTop issues:`n" + ($topErrors -join "`n")
        }

        Write-Host ""
        Write-Log "Repair request for turn #$turnNumber (attempt $attempt)" -Level "REPAIR" -Color Yellow

        $null = Write-GmExperienceLessons

        $message += " If validation_repair_request.json includes mortal_combat_state_repair or mortal_combat_state_missing, you MUST read '$($script:CompactMortalCombatTemplatePath)' and repair the existing combat scene by writing combat_log.json and relevant enemies/allies; do not delete XP/mastery/status changes."
        if ($hasDiagnosticOnlyMetadata) {
            Write-Log "  -> Skipping diagnostic-only validation repair request (metadataDiagnosticOnly=true); waiting for client-owned snapshot/metadata resolution." -Level "WARN" -Color Yellow
            $dispatchDiagnostics = [pscustomobject]@{
                Status = "skipped-diagnostic-only"
                Attempts = 0
                BusyRetries = 0
                Timeout = $false
            }
            Write-GmTrajectoryRecord `
                -Kind "repair" `
                -Mode "validation_repair" `
                -RequestObject $repair `
                -Dispatch $dispatchDiagnostics `
                -ValidationStatus "rejected" `
                -IssueKinds (Get-GmTrajectoryIssueKinds -RequestObject $repair) `
                -RepairPacketRefs (Get-GmTrajectoryRepairPacketRefs -RequestObject $repair) `
                -ValidationDiagnostics (Get-GmTrajectoryValidationDiagnostics -RequestObject $repair) `
                -RepairPacketDiagnostics (Get-GmTrajectoryRepairPacketDiagnostics -RequestObject $repair) `
                -RepairAttempts $attempt `
                -RepairStatus "diagnostic-only-skipped" `
                -MissingHarnessTool "client_owned_diagnostic_repair_resolution" `
                -StartedAtUtc $fileInfo.LastWriteTimeUtc
            return
        }

        $repairDispatchMaxWaitSeconds = if ($TurnTimeout -gt 0 -and $TurnTimeout -lt $script:BridgeDispatchMaxWaitSeconds) { $TurnTimeout } else { $script:BridgeDispatchMaxWaitSeconds }
        $dispatchDiagnostics = Dispatch-WithRetry -Message $message -PendingPath $RepairPath -ExpectedSourceHash $pendingSnapshot.Hash -OperationKind repair -OperationRevision ([string]$attempt) -ReturnDetails -MaxWaitSeconds $repairDispatchMaxWaitSeconds
        if (Test-GmPromptDispatchPaused $dispatchDiagnostics) { return }
        if ($dispatchDiagnostics.Status -eq "bridge-dispatch-timeout") {
            $script:ErrorCount++
            Write-Log "  GM bridge did not accept validation repair dispatch before the dispatch timeout; publishing repair stall report." -Level "ERROR" -Color Red
            $dispatchStall = [ordered]@{
                isStalled = $true
                completed = $false
                harnessSource = "gm_validation_repair_dispatch_unavailable"
                elapsedSeconds = $repairDispatchMaxWaitSeconds
                minimumElapsedSeconds = $repairDispatchMaxWaitSeconds
                noProgressSeconds = 0
                noProgressElapsedSeconds = $repairDispatchMaxWaitSeconds
                dispatchStatus = [string]$dispatchDiagnostics.Status
                bridgeOutputVersion = -1
                targetFiles = @()
                requestId = if ($repair.requestId) { [string]$repair.requestId } else { "" }
                turnNumber = $turnNumber
                error = "GM bridge did not accept validation repair dispatch before the dispatch timeout."
            }
            [void](Write-DaemonJsonFileBestEffort -Path $ValidationRepairArtifactStallReportFile -Payload $dispatchStall -Depth 10)
            $script:ActiveValidationRepairWatch = $null
            Write-GmTrajectoryRecord `
                -Kind "repair" `
                -Mode "validation_repair" `
                -RequestObject $repair `
                -Dispatch $dispatchDiagnostics `
                -ValidationStatus "rejected" `
                -IssueKinds (Get-GmTrajectoryIssueKinds -RequestObject $repair) `
                -RepairPacketRefs (Get-GmTrajectoryRepairPacketRefs -RequestObject $repair) `
                -ValidationDiagnostics (Get-GmTrajectoryValidationDiagnostics -RequestObject $repair) `
                -RepairPacketDiagnostics (Get-GmTrajectoryRepairPacketDiagnostics -RequestObject $repair) `
                -RepairAttempts $attempt `
                -RepairStatus "dispatch-timeout" `
                -StartedAtUtc $fileInfo.LastWriteTimeUtc `
                -MissingHarnessTool "gm_validation_repair_dispatch_unavailable"
            return
        }
        if ($dispatchDiagnostics.Status -eq "sent" -or $dispatchDiagnostics.Status -eq "clipboard") {
            $script:ActiveValidationRepairWatch = New-GmValidationRepairArtifactWatchState -RepairRequest $repair -DispatchStatus ([string]$dispatchDiagnostics.Status)
        }
        Write-GmTrajectoryRecord `
            -Kind "repair" `
            -Mode "validation_repair" `
            -RequestObject $repair `
            -Dispatch $dispatchDiagnostics `
            -ValidationStatus "rejected" `
            -IssueKinds (Get-GmTrajectoryIssueKinds -RequestObject $repair) `
            -RepairPacketRefs (Get-GmTrajectoryRepairPacketRefs -RequestObject $repair) `
            -ValidationDiagnostics (Get-GmTrajectoryValidationDiagnostics -RequestObject $repair) `
            -RepairPacketDiagnostics (Get-GmTrajectoryRepairPacketDiagnostics -RequestObject $repair) `
            -RepairAttempts $attempt `
            -RepairStatus "requested" `
            -StartedAtUtc $fileInfo.LastWriteTimeUtc
    }
    catch {
        Assert-GmNotDaemonReadFailure $_
        $script:ErrorCount++
        Write-Log "Repair watcher error: $_" -Level "ERROR" -Color Red
    }
}

{
    param([string]$FailurePath)

    if (!(Test-GmDaemonPath $FailurePath)) { return }

    try {
        $pendingSnapshot = Read-GmPromptPending -Path $FailurePath
        $fileInfo = [pscustomobject]@{LastWriteTimeUtc=$pendingSnapshot.LastWriteTimeUtc}
        if ($fileInfo.LastWriteTimeUtc -le $script:LastTerminalProtocolFailureWrite) { return }
        $script:LastTerminalProtocolFailureWrite = $fileInfo.LastWriteTimeUtc
        $failure = $pendingSnapshot.Request
        $turnNumber = if ($failure.turnNumber) { [int]$failure.turnNumber } else { -1 }
        $requestId = if ($failure.requestId) { $failure.requestId } else { "<missing-requestId>" }
        $hasDiagnosticOnlyMetadata = Test-ProtocolRequestUsesDiagnosticOnlyMetadata -RequestObject $failure

        $summary = @()
        if ($failure.summaryGroups) {
            foreach ($group in @($failure.summaryGroups | Select-Object -First 6)) {
                if ($group) { $summary += "- $group" }
            }
        }

        $topErrors = @()
        if ($failure.errors) {
            foreach ($err in @($failure.errors | Select-Object -First 5)) {
                $code = if ($err.code) { $err.code } else { "terminal_protocol_failure" }
                $category = if ($err.category) { $err.category } else { "ProtocolViolation" }
                $section = if ($err.section) { $err.section } else { "General" }
                $msg = if ($err.message) { $err.message } else { "Unknown terminal protocol failure" }
                $expected = if ($err.expected) { " Expected: $($err.expected)" } else { "" }
                $actual = if ($err.actual) { " Actual: $($err.actual)" } else { "" }
                $hint = if ($err.repairHint) { " Hint: $($err.repairHint)" } else { "" }
                $topErrors += "- [$category/$section/$code] $msg$expected$actual$hint"
            }
        }

        $message = "Terminal protocol failure for turn #$turnNumber (requestId=$requestId).$($script:GmContextPackDirective)$($script:GmDocPathDirective)$($script:GmSafeProbeDirective)$($script:GmSourceFallbackDirective)$($script:GmCompactTemplateDirective)$($script:GmExperienceLessonsDirective)$($script:GmLiveTestRubricDirective)$($script:GmTurnHelperDirective) You MUST reread $GameSessionPath\game_state\control\terminal_protocol_failure_request.json and '$($script:CompactValidationRepairTemplatePath)' before opening large copied examples. Read '$($script:TaskGuideMainPath)' for terminal protocol phase rules; use '$($script:ExampleMainPath)' only when compact templates do not cover a route-specific shape.$($script:AfterlifeRealmGateDirective)$($script:AfterlifeExamplesDirective)$($script:AfterlifeCombatConditionsDirective)$($script:AfterlifeSpecialArtCombatEffectDirective) This is NOT validation_repair_request.json and NOT a repair loop. The client already closed the current wait cycle. Do NOT create validation_repair_ready.json. Do NOT create a new turn on your own. Fix your terminal-signal discipline for the NEXT correct client request: exactly one terminal signal, terminal signal written last, never both turn_complete and turn_error for one request."
        if ($hasDiagnosticOnlyMetadata) {
            $message += " The sessionId/requestId/turnNumber in this terminal protocol failure request are diagnostic-only sentinel values because validated pending snapshot context is unavailable or invalid. Do NOT treat them as authoritative correlation metadata for the next step; restore pending snapshot context/authority first and then wait for the freshest correct client request."
        }
        else {
            $message += " Keep exact sessionId/requestId/turnNumber discipline for the NEXT correct client request."
        }
        if ($summary.Count -gt 0) {
            $message += "`nMain groups:`n" + ($summary -join "`n")
        }
        if ($topErrors.Count -gt 0) {
            $message += "`nTop issues:`n" + ($topErrors -join "`n")
        }

        Write-Host ""
        Write-Log "Terminal protocol failure for turn #$turnNumber" -Level "PROTOCOL" -Color Red

        $null = Write-GmExperienceLessons

        $dispatchDiagnostics = Dispatch-WithRetry -Message $message -PendingPath $FailurePath -ExpectedSourceHash $pendingSnapshot.Hash -OperationKind terminal-repair -ReturnDetails
        if (Test-GmPromptDispatchPaused $dispatchDiagnostics) { return }
        Write-GmTrajectoryRecord `
            -Kind "terminal" `
            -Mode "terminal_protocol" `
            -RequestObject $failure `
            -Dispatch $dispatchDiagnostics `
            -ValidationStatus "rejected" `
            -IssueKinds (Get-GmTrajectoryIssueKinds -RequestObject $failure) `
            -RepairPacketRefs (Get-GmTrajectoryRepairPacketRefs -RequestObject $failure) `
            -RepairAttempts 0 `
            -RepairStatus "none" `
            -StartedAtUtc $fileInfo.LastWriteTimeUtc `
            -MissingHarnessTool "terminal_protocol_failure"
    }
    catch {
        Assert-GmNotDaemonReadFailure $_
        $script:ErrorCount++
        Write-Log "Terminal protocol failure watcher error: $_" -Level "ERROR" -Color Red
    }
}

